                    if route_loads[b] + demands[cust] > capacity:
                        continue
                    route_a = routes[a]
                    route_b = routes[b]
                    ra = route_a[:idx] + route_a[idx + 1:]
                    if not ra:
                        continue
                    old_cost = route_cost(route_a) + route_cost(route_b)
                    pos, _ = best_insertion_position(route_b, cust)
                    rb = route_b[:]
                    rb.insert(pos, cust)
                    new_cost = route_cost(ra) + route_cost(rb)
                    if new_cost + 1e-12 < old_cost:
                        routes[a] = ra
                        routes[b] = rb
                        route_loads[a] -= demands[cust]
                        route_loads[b] += demands[cust]
                        changed = True
                        break
                if changed:
                    break

    routes = [r for r in routes if r]
    return routes
